let session=null,mode='login';
function status(msg,type=''){const el=$('#status');if(el){el.textContent=msg;el.className='status'+(type?' '+type:'')}}
async function syncCookie(s){if(!s?.access_token){await fetch('/api/logout',{method:'POST',credentials:'same-origin'}).catch(()=>{});return}const r=await fetch('/api/session',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({access_token:s.access_token,expires_in:s.expires_in||3600})});if(!r.ok)console.warn('Server session sync failed',await r.text())}
function safeNext(){const candidate=sessionStorage.getItem('hp-next')||new URLSearchParams(location.search).get('next')||'/akademie/';sessionStorage.removeItem('hp-next');return candidate.startsWith('/')&&!candidate.startsWith('//')?candidate:'/akademie/'}
async function refreshAuth(){const {data}=await db.auth.getSession();session=data.session;if(session)await syncCookie(session);updateNav();return session}
function updateNav(){const el=$('#account-link');if(el){el.textContent=session?(session.user.user_metadata?.full_name||session.user.email||'Můj účet'):'Přihlášení';el.href=session?'/akademie/':'/ucet/'}const logout=$('#logout');if(logout)logout.classList.toggle('hidden',!session)}
function authMode(next){mode=next;$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===next));const submit=$('#auth-submit');if(submit)submit.textContent=next==='recovery'?'Uložit nové heslo':next==='signup'?'Vytvořit účet':'Přihlásit se';const title=$('#auth-title');if(title)title.textContent=next==='recovery'?'Nastavit nové heslo':next==='signup'?'Vytvořit účet':'Vítejte zpět';const pass=$('#password');if(pass)pass.autocomplete=(next==='signup'||next==='recovery')?'new-password':'current-password';if(next==='recovery'){if(session?.user?.email)$('#email').value=session.user.email;status('Zadej nové heslo alespoň o 8 znacích.');}}
all('[data-mode]').forEach(b=>b.addEventListener('click',()=>authMode(b.dataset.mode)));
$('#auth-form')?.addEventListener('submit',async e=>{e.preventDefault();const email=$('#email').value.trim(),password=$('#password').value,submit=$('#auth-submit');submit.disabled=true;status(mode==='signup'?'Vytvářím účet…':'Ověřuji přihlášení…');try{let out;if(mode==='recovery'){out=await db.auth.updateUser({password});if(out.error)throw out.error;status('Nové heslo bylo uloženo.','success');await syncCookie(session);location.replace('/akademie/');return}if(mode==='signup')out=await db.auth.signUp({email,password,options:{emailRedirectTo:location.origin+'/ucet/'}});else out=await db.auth.signInWithPassword({email,password});if(out.error)throw out.error;if(mode==='signup'&&!out.data.session){status('Supabase stále vyžaduje potvrzení e-mailu. Aby registrace proběhla bez ověřovacího e-mailu, musí být v Supabase Auth vypnuté nastavení Confirm email. Účet teď není přihlášen.','error')}else{session=out.data.session;await syncCookie(session);status('Přihlášení proběhlo. Otevírám tvůj účet…','success');location.replace(safeNext())}}catch(err){status(err.message||'Přihlášení se nepodařilo.','error')}finally{submit.disabled=false}});
$('#google-login')?.addEventListener('click',async()=>{const b=$('#google-login');b.disabled=true;status('Přesměrovávám na Google…');sessionStorage.setItem('hp-next',new URLSearchParams(location.search).get('next')||'/akademie/');const {error}=await db.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+'/ucet/'}});if(error){status('Google přihlášení není nastavené nebo selhalo: '+error.message,'error');b.disabled=false}});
$('#reset-password')?.addEventListener('click',async()=>{const email=$('#email').value.trim();if(!email){status('Nejdřív zadej e-mail.','error');return}const {error}=await db.auth.resetPasswordForEmail(email,{redirectTo:location.origin+'/ucet/'});status(error?'Odkaz se nepodařilo odeslat: '+error.message:'Pokud účet existuje, přijde e-mail s odkazem pro obnovu hesla.',error?'error':'success')});
$('#logout')?.addEventListener('click',async()=>{await db.auth.signOut();await fetch('/api/logout',{method:'POST',credentials:'same-origin'});location.href='/'});
db.auth.onAuthStateChange((event,s)=>{session=s;if(event==='PASSWORD_RECOVERY'){authMode('recovery');if(s)syncCookie(s);updateNav();return}if(s){syncCookie(s).then(()=>{if(event==='SIGNED_IN'&&page==='auth'&&!location.hash.includes('type=recovery'))location.replace(safeNext())})}else fetch('/api/logout',{method:'POST',credentials:'same-origin'}).catch(()=>{});updateNav()});
async function getData(){const s=await refreshAuth();if(!s)return null;const {data,error}=await db.from('user_app_data').select('*').eq('user_id',s.user.id).maybeSingle();if(error)throw error;return data}
async function saveData(patch){if(!session)throw new Error('Nejdřív se přihlas.');const old=await getData();const row={user_id:session.user.id,display_name:session.user.user_metadata?.full_name||session.user.email||'',dog_profile:old?.dog_profile||{},progress:old?.progress||{points:0,activities:0,completedMissions:[],completedLessons:[]},missions:old?.missions||{},card_profile:old?.card_profile||{},quiz_results:old?.quiz_results||{},...patch,updated_at:new Date().toISOString()};const {error}=await db.from('user_app_data').upsert(row,{onConflict:'user_id'});if(error)throw error;return row}
