  let dogs=dogsData||[];
  // Preserve the previous JSON profile by copying it into the new table only if no new profiles exist.
  if(!dogs.length){const legacy=await getData();const old=legacy?.dog_profile||{};if(old.name){const {data:migrated,error:migErr}=await db.from('dog_profiles').insert({user_id:session.user.id,name:String(old.name).slice(0,80),breed_name:String(old.breed||'').slice(0,160),temperament:String(old.superpower||''),goals:String(old.challenge||''),size:'unknown'}).select().single();if(!migErr&&migrated)dogs=[migrated]}}
  const setField=(name,value)=>{const el=form.elements.namedItem(name);if(el)el.value=value??''};
