  const editDog=dog=>{setField('id',dog.id);setField('name',dog.name);setField('breed_name',dog.breed_name);setField('birth_date',dog.birth_date);setField('sex',dog.sex||'unknown');setField('photo_url',dog.photo_url);setField('size',dog.size||'unknown');setField('weight_kg',dog.weight_kg);setField('coat_color',dog.coat_color);setField('temperament',dog.temperament);setField('goals',dog.goals);setField('health_notes',dog.health_notes);setField('adoption',dog.adoption);setField('activities_text',(dog.activities||[]).join(', '));$('#profile-form-title').textContent='Upravit: '+dog.name;preview();form.scrollIntoView({behavior:'smooth',block:'start'})};
  const renderDogs=()=>{list.innerHTML='';if(!dogs.length){const p=document.createElement('p');p.className='muted';p.textContent='Zatím nemáš uloženého žádného psa. Přidej první profil vlevo.';list.append(p);return}dogs.forEach(dog=>{const card=document.createElement('article');card.className='dog-card';if(dog.photo_url&&/^https?:\/\//i.test(dog.photo_url)){const img=document.createElement('img');img.src=dog.photo_url;img.alt='Fotografie psa '+dog.name;img.loading='lazy';img.className='dog-avatar';img.onerror=()=>img.remove();card.append(img)}const info=document.createElement('div');info.className='dog-card-info';const h=document.createElement('h3');h.textContent=dog.name;const meta=document.createElement('p');meta.textContent=[dog.breed_name||'Plemeno neuvedeno',dog.birth_date?'Narozen/a '+new Date(dog.birth_date+'T12:00:00').toLocaleDateString('cs-CZ'):'',({female:'Fena',male:'Pes',unknown:'Pohlaví neuvedeno'})[dog.sex]||''].filter(Boolean).join(' · ');const goals=document.createElement('small');goals.textContent=dog.goals?'Cíle: '+dog.goals:'Cíle zatím nejsou vyplněné.';info.append(h,meta,goals);const actions=document.createElement('div');actions.className='dog-card-actions';const edit=document.createElement('button');edit.className='btn light';edit.type='button';edit.textContent='Upravit';edit.addEventListener('click',()=>editDog(dog));const del=document.createElement('button');del.className='btn light';del.type='button';del.textContent='Smazat';del.addEventListener('click',async()=>{if(!confirm('Opravdu smazat profil '+dog.name+'? Historické záznamy budou zachovány bez vazby na tento profil.'))return;const {error}=await db.from('dog_profiles').delete().eq('id',dog.id).eq('user_id',session.user.id);if(error){status('Profil se nepodařilo smazat: '+error.message,'error');return}dogs=dogs.filter(x=>x.id!==dog.id);renderDogs();resetForm();status('Profil psa smazán.','success')});actions.append(edit,del);card.append(info,actions);list.append(card)})};
