const loadEvents=async()=>{const {data,error}=await db.from('site_events').select('*').order('created_at',{ascending:false});if(error)throw error;const list=$('#admin-events');list.innerHTML='';(data||[]).forEach(ev=>{const row=document.createElement('label');row.className='item check';const cb=document.createElement('input');cb.type='checkbox';cb.checked=ev.published;cb.addEventListener('change',async()=>{const {error}=await db.from('site_events').update({published:cb.checked,updated_at:new Date().toISOString()}).eq('id',ev.id);if(error)status(error.message,'error');else status('Publikace akce změněna.','success')});const copy=document.createElement('span');copy.innerHTML='<strong></strong><small></small>';copy.children[0].textContent=ev.title;copy.children[1].textContent=ev.starts_at||'Bez termínu';row.append(cb,copy);list.append(row)});const {data:users,error:userError}=await db.from('user_app_data').select('user_id,display_name,dog_profile,updated_at').order('updated_at',{ascending:false}).limit(100);if(!userError&&$('#admin-users')){const tb=$('#admin-users');tb.innerHTML='';(users||[]).forEach(u=>{const tr=document.createElement('tr');[u.display_name||'Uživatel',u.dog_profile?.name||'—',u.updated_at?new Date(u.updated_at).toLocaleDateString('cs-CZ'):'—'].forEach(v=>{const td=document.createElement('td');td.textContent=v;tr.append(td)});tb.append(tr)})}};
