const loadAcademyContent=async()=>{const {data,error}=await db.from('academy_content').select('id,category,title,body,published,verified,source_url,level').order('created_at',{ascending:false});if(error)throw error;const list=$('#academy-content-list');if(!list)return;list.innerHTML='';(data||[]).forEach(item=>{const row=document.createElement('label');row.className='item check';const cb=document.createElement('input');cb.type='checkbox';cb.checked=item.published;cb.addEventListener('change',async()=>{const {error}=await db.from('academy_content').update({published:cb.checked,updated_at:new Date().toISOString()}).eq('id',item.id);if(error)status(error.message,'error');else status('Publikace akademického obsahu změněna.','success')});const copy=document.createElement('span');const strong=document.createElement('strong');strong.textContent=item.title;const small=document.createElement('small');small.textContent=item.category+' · '+item.level+' · '+(item.verified?'ověřený zdroj':'zdroj neověřen');copy.append(strong,small);row.append(cb,copy);list.append(row)})};
const loadBreeds=async()=>{const {data,error}=await db.from('breed_catalog').select('id,name,registry,recognition,verified,active,source_url').order('name').limit(500);if(error)throw error;const list=$('#breed-admin-list');if(!list)return;list.innerHTML='';(data||[]).forEach(b=>{const row=document.createElement('label');row.className='item check';const cb=document.createElement('input');cb.type='checkbox';cb.checked=b.active;cb.addEventListener('change',async()=>{const {error}=await db.from('breed_catalog').update({active:cb.checked,updated_at:new Date().toISOString()}).eq('id',b.id);if(error)status(error.message,'error');else status('Viditelnost plemene změněna.','success')});const copy=document.createElement('span');const strong=document.createElement('strong');strong.textContent=b.name;const small=document.createElement('small');small.textContent=b.registry+' · '+b.recognition+' · '+(b.verified?'ověřeno':'neověřeno');copy.append(strong,small);row.append(cb,copy);list.append(row)})};
