const loadProgress=async()=>{const [{data:dogs,error:dogsErr},{data:done,error:doneErr},{data:pullers,error:pullerErr}]=await Promise.all([db.from('dog_profiles').select('user_id,name'),db.from('academy_completions').select('user_id,activity_type,points,completed_at').order('completed_at',{ascending:false}).limit(300),db.from('dog_puller_sessions').select('user_id,duration_minutes,created_at').order('created_at',{ascending:false}).limit(300)]);if(dogsErr)throw dogsErr;if(doneErr)throw doneErr;if(pullerErr)throw pullerErr;const ids=[...new Set([...(dogs||[]).map(x=>x.user_id),...(done||[]).map(x=>x.user_id),...(pullers||[]).map(x=>x.user_id)])];const list=$('#admin-progress-list');if(!list)return;list.innerHTML='';if(!ids.length){list.textContent='Zatím nejsou uložené nové profily nebo aktivity.';return}ids.forEach(id=>{const row=document.createElement('div');row.className='item';const strong=document.createElement('strong');strong.textContent=id;const small=document.createElement('small');small.textContent=(dogs||[]).filter(x=>x.user_id===id).length+' psů · '+(done||[]).filter(x=>x.user_id===id).length+' dokončených aktivit · '+(pullers||[]).filter(x=>x.user_id===id).length+' Dog Puller záznamů';row.append(strong,small);list.append(row)})};

